// Step 1 — VALIDATE payload (mirrors flows.appointment._validate_payload).
// Required: payload.patient.(name|phone|email) AND payload.requested_window.{start,end}.

const p = $json.body || $json || {};
const patient = (p.patient && typeof p.patient === 'object') ? p.patient : {};
const patientId = (patient.name || patient.phone || patient.email || '').toString().trim();
const window = (p.requested_window && typeof p.requested_window === 'object') ? p.requested_window : {};
const start = (window.start || '').toString().trim();
const end = (window.end || '').toString().trim();

const errors = [];
if (!patientId) errors.push('payload.patient requires name/phone/email');
if (!start || !end) errors.push('payload.requested_window must include start AND end');

const requestId = 'appt-' + Math.random().toString(16).slice(2, 14);

return [{
  json: {
    request_id: requestId,
    valid: errors.length === 0,
    errors,
    req: {
      patient_id: patientId,
      patient_label: patient.name || patientId,
      patient_phone: patient.phone || (patientId.startsWith('+') ? patientId : null),
      window_start: start,
      window_end: end,
      preferred_slot: p.preferred_slot || null,
      provider: p.provider || null,
      reason: p.reason || null,
      actor: p.actor || 'system:n8n-appointment-flow',
      appointment_source: p.appointment_source || 'svigg',
      billing_source: p.billing_source || 'picasso',
    }
  }
}];

// Parse lookup_patient stdout and decide if any source matched.
// Carry forward the original req payload alongside the lookup result.

const raw = $json.stdout || '{}';
let lookup;
try {
  lookup = JSON.parse(raw);
} catch (e) {
  lookup = { results: [], error: 'lookup_parse_failed: ' + e.message };
}
const matched = (lookup.results || []).filter(r => r.record).map(r => r.source);

// Pull the validated request back out of the previous Function node so this
// branch keeps everything downstream nodes need on `$json.req`.
const req = $items('Function: Validate payload', 0, 0).json.req;
const requestId = $items('Function: Validate payload', 0, 0).json.request_id;

return [{
  json: {
    request_id: requestId,
    req,
    patient_lookup: lookup,
    patient_matched: matched.length > 0,
    matched_sources: matched,
  }
}];

// Detect conflicts (mirrors flows.appointment._detect_conflicts).
//   same_patient_in_window: appointment.name matches our patient and falls in window
//   slot_taken: appointment date equals preferred_slot date

const raw = $json.stdout || '{}';
let book;
try { book = JSON.parse(raw); } catch (e) { book = { appointments: [] }; }
const appts = book.appointments || [];

const prev = $items('Function: Parse lookup result', 0, 0).json;
const req = prev.req;
const lookup = prev.patient_lookup;

const names = new Set();
for (const r of (lookup.results || [])) {
  const n = ((r.record && r.record.name) || '').toString().trim().toLowerCase();
  if (n) names.add(n);
}
if (req.patient_label) names.add(req.patient_label.trim().toLowerCase());

const preferred = (req.preferred_slot || '').toString().trim();
const preferredDate = preferred.includes('T') ? preferred.split('T')[0] : preferred;

const conflicts = [];
for (const a of appts) {
  const an = (a.name || '').toString().trim().toLowerCase();
  let ad = (a.intake_date || '').toString();
  if (ad.includes('/')) {
    const [m, d, y] = ad.split('/');
    if (m && d && y) ad = `${y}-${m.padStart(2,'0')}-${d.padStart(2,'0')}`;
  }
  if (an && names.has(an)) {
    conflicts.push({ type: 'same_patient_in_window', appointment: a });
    continue;
  }
  if (preferredDate && ad === preferredDate) {
    conflicts.push({ type: 'slot_taken', appointment: a });
  }
}

return [{
  json: {
    request_id: prev.request_id,
    req,
    patient_lookup: lookup,
    appointments_in_window: appts,
    conflicts,
  }
}];

// Merge billing into the running payload, summarize for the staff SMS.
const raw = $json.stdout || '{}';
let billing;
try { billing = JSON.parse(raw); } catch (e) { billing = { ledgers: [] }; }

const prev = $items('Function: Detect conflicts', 0, 0).json;

let bSummary = { balance: null, insurance: null, found: false };
for (const led of (billing.ledgers || [])) {
  if (led.found) {
    bSummary = {
      balance: led.balance, insurance: led.insurance,
      status: led.status, source: led.source, found: true,
    };
    break;
  }
}

return [{
  json: { ...prev, billing, billing_summary: bSummary }
}];

