// Compose Q4 staff-approval SMS body (mirrors _build_staff_sms_body).
const prev = $items('Function: Summarize billing', 0, 0).json;
const req = prev.req;
const conflicts = prev.conflicts || [];
const bs = prev.billing_summary || {};

let auditIds = [];
try { auditIds = (JSON.parse($json.stdout || '{}').audit_row_ids) || []; } catch (e) {}

const balance = (bs.balance === null || bs.balance === undefined || bs.balance === '') ? '—' : ('$' + bs.balance);
const conflictStr = conflicts.length
  ? `${conflicts.length} (${conflicts.slice(0,3).map(c=>c.type).join(', ')})`
  : 'none';
const reason = (req.reason || '—').slice(0, 120);

const body = [
  `[APW] Appointment request ${prev.request_id}`,
  `Patient: ${req.patient_label}`,
  `Window: ${req.window_start} -> ${req.window_end}`,
  `Slot:    ${req.preferred_slot || '—'}`,
  `Provider: ${req.provider || '—'}`,
  `Reason:  ${reason}`,
  `Balance: ${balance}`,
  `Conflicts: ${conflictStr}`,
  'Reply YES to confirm, NO to reject, EDIT to staff-handle.',
].join('\n');

return [{
  json: {
    ...prev,
    audit_row_ids: auditIds,
    staff_sms_body: body,
    staff_to: process.env.APPROVAL_STAFF_NUMBER || '',
    from_did: process.env.CLINIC_SMS_FROM_NUMBER || ''
  }
}];

// Send patient confirmation only if the inbound payload gave us a phone-shaped
// id (per Q9 boundary — never scrape a phone we weren't explicitly given).
const prev = $items('Function: Compose staff SMS', 0, 0).json;
const phone = prev.req.patient_phone || '';
const looksLikePhone = /^\+?\d{10,11}$/.test(phone.replace(/\D/g, '').padStart(11, ''));
const mainLine = process.env.CLINIC_MAIN_LINE || 'the clinic';
const body = `This is Atlantic Pain & Wellness. We received your appointment request and a staff member will follow up shortly. For urgent issues, call ${mainLine}. For emergencies, call 911.`;

let staffMsgId = null;
try { staffMsgId = (JSON.parse($json.stdout || '{}').id) || null; } catch (e) {}

return [{
  json: {
    ...prev,
    staff_sms_message_id: staffMsgId,
    should_send_patient_sms: looksLikePhone && !!phone,
    patient_to: phone,
    patient_sms_body: body,
  }
}];

// Build the final response payload: identical shape to flows.appointment.run().
const prev = $items('Function: Compose patient SMS', 0, 0).json;

let patientMsgId = null;
if ($json && $json.stdout) {
  try { patientMsgId = (JSON.parse($json.stdout).id) || null; } catch (e) {}
}

return [{
  json: {
    request_id: prev.request_id,
    ok: true,
    pending_approval: true,
    reserved: false,
    patient: prev.patient_lookup,
    appointments_in_window: prev.appointments_in_window,
    conflicts: prev.conflicts,
    billing: prev.billing,
    staff_sms_message_id: prev.staff_sms_message_id,
    patient_sms_message_id: patientMsgId,
    audit_row_ids: prev.audit_row_ids,
    errors: [],
  }
}];

// Validation failure branch — return 400-style payload.
return [{
  json: {
    request_id: $json.request_id,
    ok: false,
    pending_approval: false,
    reserved: false,
    patient: {},
    appointments_in_window: [],
    conflicts: [],
    billing: {},
    staff_sms_message_id: null,
    patient_sms_message_id: null,
    audit_row_ids: [],
    errors: $json.errors.map(e => 'validation: ' + e),
  }
}];

// Patient not found — fail closed, do NOT proceed to scheduling.
const prev = $items('Function: Parse lookup result', 0, 0).json;
return [{
  json: {
    request_id: prev.request_id,
    ok: false,
    pending_approval: false,
    reserved: false,
    patient: prev.patient_lookup,
    appointments_in_window: [],
    conflicts: [],
    billing: {},
    staff_sms_message_id: null,
    patient_sms_message_id: null,
    audit_row_ids: [],
    errors: ['patient_not_found: no match for ' + prev.req.patient_id + ' in any source'],
  }
}];
